const log = find_block({ names: ['oak_log', 'birch_log', 'spruce_log'], max_distance: 24 });
if (!log) {
  return { done: false, detail: 'no tree within 24 blocks' };
}
const chopped = await dig(log.x, log.y, log.z);
if (!chopped.ok) {
  return { done: false, detail: chopped.detail };
}
const left = await leave_at_depot('oak_log', 1);
if (!left.ok) {
  return { done: true, detail: 'mined a log; ' + left.detail };
}
return { done: true, detail: 'mined a log and left it at the depot' };
